import { R, X, lesson, mcq, numeric, short } from './helpers';
import type { Lesson } from '@/lib/types';

/**
 * AI + ROBOTICS / Localization and Navigation.
 *
 * The NAVIGATION track: how a robot knows where it is, builds a map of a world
 * it has never seen, and moves through it safely. Estimation comes first
 * (Kalman, then nonlinear variants), because SLAM is estimation with a growing
 * state, and because a planner that does not understand its own uncertainty will
 * confidently drive into a wall.
 *
 * Order: the localization problem -> the Kalman filter -> nonlinear estimation
 * (EKF, particle filter) -> mapping and scan matching -> SLAM and loop closure ->
 * local motion (path following, DWA) -> integration, recovery and verification.
 */
